INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('onboarding', '{"method":"online_payment","reminder_days":[3,1],"whatsapp_number":null,"whatsapp_template":"Hello Fullfilio, I have just signed up and would like my account activated.\nBusiness: {business}\nName: {name}\nMobile: {phone}\nE-mail: {email}\nPlan: {plan} ({price} / {interval})"}', 'How new businesses are activated (online payment or WhatsApp) and when expiry reminders go out', NULL, '2026-10-30T09:37:09.094Z', '2026-10-30T09:37:09.094Z');
