INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('billing_gateways', '{"bkash":{"enabled":false,"sandbox":true},"paystation":{"enabled":false,"sandbox":true},"sslcommerz":{"enabled":false,"sandbox":true}}', 'Gateways merchants use to pay invoices and buy credits (platform accounts)', NULL, '2026-10-30T09:37:08.651Z', '2026-10-30T09:37:09.432Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('signup_offer', '{"enabled":false,"trial_days":2,"first_price":99,"first_periods":1}', 'New businesses: free trial days, then the first period(s) at an introductory price, then the plan price', NULL, '2026-10-30T09:37:09.439Z', '2026-10-30T09:37:09.439Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('access_rules', '{"ACTIVE":"FULL","PAUSED":"READ_ONLY","EXPIRED":"BLOCKED","PAST_DUE":"FULL","TRIALING":"FULL","CANCELLED":"READ_ONLY","TRIAL_ENDED":"BLOCKED","NO_SUBSCRIPTION":"FULL","MERCHANT_SUSPENDED":"BLOCKED","MERCHANT_ONBOARDING":"FULL","PAST_DUE_AFTER_GRACE":"READ_ONLY"}', 'What each account state allows: FULL, READ_ONLY (look but not change; customers can still order) or BLOCKED (no admin, no new orders)', NULL, '2026-10-30T09:37:08.569Z', '2026-10-30T09:37:09.439Z');
INSERT INTO "platform_settings" ("key", "value", "description", "updated_by", "created_at", "updated_at") VALUES ('email_service', '{"enabled":false,"from_name":"","from_email":"","daily_limit":300}', 'Fullfilio email service (Resend): sender address and the daily limit per store. The API key lives in Vault (email.resend).', NULL, '2026-10-30T09:37:09.559Z', '2026-10-30T09:37:09.559Z');
